<?php require '_top.php'; $counts=[];foreach(['conteudos','kpis','equipe','contatos'] as $t)$counts[$t]=db()->query("SELECT COUNT(*) FROM $t")->fetchColumn();?><p class="eyebrow">PAINEL</p><h1>Olá, <?=e($_SESSION['user']['nome'])?></h1><div class="grid metrics"><?php foreach($counts as $n=>$v):?><article><b><?=e($n)?></b><strong><?=$v?></strong></article><?php endforeach?></div><h2>Últimas mensagens</h2><div class="cards grid"><?php foreach(db()->query('SELECT nome,assunto,criado_em FROM contatos ORDER BY criado_em DESC LIMIT 3') as $x):?><article><h3><?=e($x['nome'])?></h3><p><?=e($x['assunto'])?></p><small><?=e($x['criado_em'])?></small></article><?php endforeach?></div><?php require '_bottom.php'; ?>
